import { isUndefined } from 'lodash-es';
import React, { useRef } from 'react';

import { container } from './TreeMapOverlay.sty.js';
import { useGraphSize } from '../../../core/components/chart-layout/hooks/useGraphSize.js';
import { useToolbarConfig } from '../../context/ToolbarContext.js';
import { useOverlayHandlers } from '../../hooks/useOverlayHandlers.js';
import { useTooltipEventListeners } from '../../hooks/useTooltipEventListeners.js';
import type { TreeMapMetadata } from '../../types/internal.js';
import { TreeMapToolbar } from '../TreeMapToolbar/TreeMapToolbar.js';
import { TreeMapTooltip } from '../TreeMapTooltip/TreeMapTooltip.js';

interface TreeMapOverlayProps {
  metadata: TreeMapMetadata;
}

export const TreeMapOverlay = (props: TreeMapOverlayProps) => {
  const tooltipRef = useRef<HTMLDivElement>(null);
  const { metadata } = props;
  const { width, height } = useGraphSize();
  const {
    onMouseMoveHandler,
    onMouseLeaveHandler,
    onClickHandler,
    onMouseEnterHandler,
  } = useOverlayHandlers();

  const toolbarConfig = useToolbarConfig();
  const shouldShowToolbar = !isUndefined(toolbarConfig);
  useTooltipEventListeners(tooltipRef.current);

  return (
    <div
      style={{ width, height }}
      className={container}
      onClick={onClickHandler}
      onMouseEnter={onMouseEnterHandler}
      onMouseMove={onMouseMoveHandler}
      onMouseLeave={onMouseLeaveHandler}
    >
      <TreeMapTooltip metadata={metadata} ref={tooltipRef} />
      {shouldShowToolbar && <TreeMapToolbar />}
    </div>
  );
};

TreeMapOverlay['displayName'] = 'TreeMapOverlay';
